  ["_CeladonGymBattleText3"] = "Cominciavo\na annoiarmi.",
  ["_CeladonGymBattleText4"] = "Non\nsarai mica un\11voyeur?",
  ["_CeladonGymBattleText5"] = "Guarda\ni miei POKéMON\11Erba! é cosi'\nfacile allevarli!",
  ["_CeladonGymBattleText6"] = "Non\nportare POKéMON\11Insetto o Fuoco\nqui dentro!",
  ["_CeladonGymBattleText7"] = "Piacere\ndi conoscerti. Il\11mio hobby é\nl'allenamento\11POKéMON.",
