  ["_CeladonGymEndBattleText2"] = "Sei\ntroppo rozzo!",
  ["_CeladonGymEndBattleText3"] = "Il\nmio trucco!",
  ["_CeladonGymEndBattleText4"] = "Sono\nchoc!",
  ["_CeladonGymEndBattleText5"] = "No!",
  ["_CeladonGymEndBattleText6"] = "Oh!\nTu!",
  ["_CeladonGymEndBattleText7"] = "Oh!\nSplendido!",
  ["_CeladonGymEndBattleText8"] = "Oh!\nBattuta!",
