  ["_CeladonGymErikaPreBattleText"] = "Salve. Che\nbel\ntempo, vero?\12é cosi' piacevole.\n...Oh cielo...\11Mi sono\nappisolata.\nBenvenuto.\12Mi chiamo ERIKA.\nSono la\nCAPOPALESTRA\11di AZZURROPOLI.\12Insegno l'arte\ndell'ikebana. I\nmiei\11POKéMON sono di\11tipo Erba.\12Oh, perdona, non\nsapevo volessi\11sfidarmi.\12Va bene, ma non\nterro' testa\nbassa.",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "Oh! Ammetto la\nsconfitta. Sei\11davvero molto\nforte. Devo\11conferirti il\nMEDAGLIA\11ARCOBALENO.",
  ["_CeladonGymRainbowBadgeInfoText"] = "Il MEDAGLIA\nARCOBALENO\nfara' ubbidire i\nPOKéMON\11fino al Lv. 50.\12Permette anche di\nusare FORZA dentro\11e fuori la lotta.\12Prendi anche\nquesto con te.",
