  ["_CinnabarGymSuperNerd5EndBattleText"] = "Ahi!",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "A noi\nfan dei POKéM.\11Fuoco piacciono\nPONYTA e\11NINETALES!",
